class Solution:
    def maximumSaleItems(self, items: List[List[int]], budget: int) -> int:
        n = len(items)

        free = [0] * n

        # Calculate free copies generated by each item
        for i in range(n):
            for j in range(n):
                if i != j and items[j][0] % items[i][0] == 0:
                    free[i] += 1

        # Reward = purchased copy + free copies
        groups = {}
        for i in range(n):
            f, p = items[i]
            groups.setdefault(p, []).append(1 + free[i])

        dp = [-10**9] * (budget + 1)
        dp[0] = 0

        with_current = [-10**9] * (budget + 1)

        ans = 0

        # Process prices from highest to lowest
        for price in sorted(groups.keys(), reverse=True):

            with_current = [-10**9] * (budget + 1)

            for reward in groups[price]:
                for b in range(budget, price - 1, -1):

                    with_current[b] = max(
                        with_current[b],
                        dp[b - price] + reward,
                        with_current[b - price] + reward
                    )

                    dp[b] = max(
                        dp[b],
                        dp[b - price] + reward
                    )

            # Calculate maximum total items
            for b in range(budget + 1):
                if with_current[b] >= 0:
                    ans = max(
                        ans,
                        with_current[b] + (budget - b) // price
                    )

        return ans